1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    padding: 2rem 1rem;
12	    font: 16px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
13	    background: #f5f5f4;
14	    color: #1c1917;
15	  }
16	  main { max-width: 32rem; margin: 0 auto; }
17	  h1 { margin: 0 0 1rem; font-size: 1.5rem; }
18	  form { display: flex; gap: 0.5rem; }
19	  input[type="text"] {
20	    flex: 1;
21	    min-width: 0;
22	    padding: 0.6rem 0.75rem;
23	    font: inherit;
24	    border: 1px solid #d6d3d1;
25	    border-radius: 6px;
26	    background: #fff;
27	  }
28	  button {
29	    padding: 0.6rem 1rem;
30	    font: inherit;
31	    border: 0;
32	    border-radius: 6px;
33	    background: #1c1917;
34	    color: #fff;
35	    cursor: pointer;
36	  }
37	  ul { list-style: none; margin: 1rem 0 0; padding: 0; }
38	  li {
39	    display: flex;
40	    align-items: center;
41	    gap: 0.5rem;
42	    padding: 0.6rem 0.75rem;
43	    margin-bottom: 0.5rem;
44	    background: #fff;
45	    border: 1px solid #e7e5e4;
46	    border-radius: 6px;
47	  }
48	  li span { flex: 1; overflow-wrap: anywhere; }
49	  li button { background: transparent; color: #b91c1c; padding: 0.25rem 0.5rem; }
50	  li button:hover { background: #fee2e2; }
51	  li input[type="checkbox"] { width: 1.1rem; height: 1.1rem; margin: 0; cursor: pointer; }
52	  li[data-completed="true"] span { color: #a8a29e; text-decoration: line-through; }
53	  input[type="date"], select {
54	    padding: 0.5rem;
55	    font: inherit;
56	    border: 1px solid #d6d3d1;
57	    border-radius: 6px;
58	    background: #fff;
59	  }
60	  li .due { flex: none; font-size: 0.85rem; color: #57534e; }
61	  li[data-overdue="true"] { border-color: #fca5a5; background: #fef2f2; }
62	  li[data-overdue="true"] .due { color: #b91c1c; font-weight: 600; }
63	  /* [REQ-004] Priority colour: left stripe, set after overdue so it keeps its own colour. */
64	  li[data-priority] { border-left-width: 4px; }
65	  li[data-priority="high"] { border-left-color: #dc2626; }
66	  li[data-priority="med"] { border-left-color: #f59e0b; }
67	  li[data-priority="low"] { border-left-color: #a8a29e; }
68	  .filters { display: flex; gap: 0.5rem; margin-top: 1rem; }
69	  .filters button { background: transparent; color: #1c1917; border: 1px solid #d6d3d1; padding: 0.35rem 0.75rem; }
70	  .filters button[aria-pressed="true"] { background: #1c1917; color: #fff; border-color: #1c1917; }
71	</style>
72	</head>
73	<body>
74	<main>
75	  <h1>Todos</h1>
76	  <form id="todo-form">
77	    <input type="text" data-testid="todo-input" placeholder="What needs doing?" autocomplete="off" aria-label="New todo">
78	    <input type="date" data-testid="todo-due" aria-label="Due date (optional)">
79	    <select data-testid="todo-priority" aria-label="Priority">
80	      <option value="low">Low</option>
81	      <option value="med" selected>Med</option>
82	      <option value="high">High</option>
83	    </select>
84	    <button type="submit" data-testid="todo-add">Add</button>
85	  </form>
86	  <div class="filters" role="group" aria-label="Filter todos">
87	    <button type="button" data-testid="filter-all" data-filter="all" aria-pressed="true">All</button>
88	    <button type="button" data-testid="filter-active" data-filter="active" aria-pressed="false">Active</button>
89	    <button type="button" data-testid="filter-completed" data-filter="completed" aria-pressed="false">Completed</button>
90	  </div>
91	  <ul data-testid="todo-list"></ul>
92	</main>
93	<script>
94	(function () {
95	  var STORAGE_KEY = 'todos';
96	  var form = document.getElementById('todo-form');
97	  var input = document.querySelector('[data-testid="todo-input"]');
98	  var list = document.querySelector('[data-testid="todo-list"]');
99	  var dueInput = document.querySelector('[data-testid="todo-due"]');
100	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
101	
102	  // [REQ-001]
103	  function makeId() {
104	    if (window.crypto && typeof window.crypto.randomUUID === 'function') {
105	      return window.crypto.randomUUID();
106	    }
107	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
108	  }
109	
110	  // [REQ-001]
111	  function loadTodos() {
112	    try {
113	      var parsed = JSON.parse(localStorage.getItem(STORAGE_KEY));
114	      return Array.isArray(parsed) ? parsed : [];
115	    } catch (e) {
116	      return [];
117	    }
118	  }
119	
120	  // [REQ-001]
121	  function saveTodos() {
122	    try {
123	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
124	    } catch (e) {}
125	  }
126	
127	  var todos = loadTodos();
128	  var filter = 'all';
129	  var filterButtons = document.querySelectorAll('[data-filter]');
130	
131	  // [REQ-002] Active todos first, then completed; each group keeps insertion order.
132	  function orderedTodos() {
133	    var active = todos.filter(function (t) { return !t.completed; });
134	    var done = todos.filter(function (t) { return !!t.completed; });
135	    return active.concat(done);
136	  }
137	
138	  // [REQ-003] Today's LOCAL calendar date as YYYY-MM-DD (never via UTC).
139	  function todayLocal() {
140	    var d = new Date();
141	    var m = d.getMonth() + 1;
142	    var day = d.getDate();
143	    return d.getFullYear() + '-' + (m < 10 ? '0' : '') + m + '-' + (day < 10 ? '0' : '') + day;
144	  }
145	
146	  // [REQ-003] Accept only a plain YYYY-MM-DD string; anything else means no due date.
147	  function normalizeDue(value) {
148	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : '';
149	  }
150	
151	  // [REQ-003] Overdue = due date strictly before today's local date. Date-only string compare.
152	  function isOverdue(todo, today) {
153	    var due = normalizeDue(todo.due);
154	    return due !== '' && due < today;
155	  }
156	
157	  // [REQ-004] Only low, med or high; anything else (including older todos) is med.
158	  function normalizePriority(value) {
159	    return value === 'low' || value === 'high' ? value : 'med';
160	  }
161	
162	  // [REQ-002]
163	  function isVisible(todo) {
164	    if (filter === 'active') return !todo.completed;
165	    if (filter === 'completed') return !!todo.completed;
166	    return true;
167	  }
168	
169	  // [REQ-001]
170	  function render() {
171	    list.textContent = '';
172	    filterButtons.forEach(function (btn) {
173	      btn.setAttribute('aria-pressed', String(btn.getAttribute('data-filter') === filter));
174	    });
175	    var today = todayLocal();
176	    orderedTodos().filter(isVisible).forEach(function (todo) {
177	      var li = document.createElement('li');
178	      li.setAttribute('data-testid', 'todo-item');
179	      li.setAttribute('data-id', todo.id);
180	      li.setAttribute('data-completed', String(!!todo.completed));
181	      li.setAttribute('data-overdue', String(isOverdue(todo, today)));
182	      li.setAttribute('data-priority', normalizePriority(todo.priority)); // [REQ-004]
183	
184	      var toggle = document.createElement('input');
185	      toggle.type = 'checkbox';
186	      toggle.setAttribute('data-testid', 'todo-toggle');
187	      toggle.setAttribute('aria-label', 'Mark complete');
188	      toggle.checked = !!todo.completed;
189	      toggle.addEventListener('change', function () { toggleTodo(todo.id); });
190	      li.appendChild(toggle);
191	
192	      var text = document.createElement('span');
193	      text.setAttribute('data-testid', 'todo-text');
194	      text.textContent = todo.text;
195	
196	      var del = document.createElement('button');
197	      del.type = 'button';
198	      del.setAttribute('data-testid', 'todo-delete');
199	      del.setAttribute('aria-label', 'Delete todo');
200	      del.textContent = 'Delete';
201	      del.addEventListener('click', function () { deleteTodo(todo.id); });
202	
203	      li.appendChild(text);
204	
205	      // [REQ-003] Show the stored string as-is so no timezone shift can occur.
206	      var due = normalizeDue(todo.due);
207	      if (due) {
208	        var dueEl = document.createElement('span');
209	        dueEl.className = 'due';
210	        dueEl.setAttribute('data-testid', 'todo-due-date');
211	        dueEl.textContent = 'Due ' + due;
212	        li.appendChild(dueEl);
213	      }
214	
215	      li.appendChild(del);
216	      list.appendChild(li);
217	    });
218	  }
219	
220	  // [REQ-001]
221	  function addTodo(text, due, priority) {
222	    text = text.trim();
223	    if (!text) return;
224	    // [REQ-003] due is optional, stored as a YYYY-MM-DD string or ''.
225	    todos.push({ id: makeId(), text: text, createdAt: Date.now(), completed: false, due: normalizeDue(due), priority: normalizePriority(priority) }); // [REQ-004]
226	    saveTodos();
227	    render();
228	  }
229	
230	  // [REQ-002]
231	  function toggleTodo(id) {
232	    todos.forEach(function (t) {
233	      if (t.id === id) t.completed = !t.completed;
234	    });
235	    saveTodos();
236	    render();
237	  }
238	
239	  // [REQ-002]
240	  function setFilter(value) {
241	    filter = value;
242	    render();
243	  }
244	
245	  filterButtons.forEach(function (btn) {
246	    btn.addEventListener('click', function () { setFilter(btn.getAttribute('data-filter')); });
247	  });
248	
249	  // [REQ-001]
250	  function deleteTodo(id) {
251	    todos = todos.filter(function (t) { return t.id !== id; });
252	    saveTodos();
253	    render();
254	  }
255	
256	  form.addEventListener('submit', function (e) {
257	    e.preventDefault();
258	    addTodo(input.value, dueInput.value, priorityInput.value);
259	    input.value = '';
260	    dueInput.value = '';
261	    priorityInput.value = 'med';
262	    input.focus();
263	  });
264	
265	  // [REQ-003] Refresh overdue state when the page returns after the date may have changed.
266	  document.addEventListener('visibilitychange', function () {
267	    if (!document.hidden) render();
268	  });
269	
270	  render();
271	})();
272	</script>
273	</body>
274	</html>
